// Russian Roulette - Spin Picker (raylib)
// Resizable window, background fills the whole window, entries/options panel on the right.
// Build: gcc russian_roulette_single.c -o russian_roulette -lraylib -lm  (same flags as your other games)
// Images: the background (table), shotgun and shells are embedded below as base64.
//         Optional: put an assets/ folder next to this file (table.png etc.) as a fallback.
