// Works with both raylib 5.5+ (4-arg) and older versions (5-arg with line thickness)
#if defined(RAYLIB_VERSION_MAJOR) && (RAYLIB_VERSION_MAJOR > 5 || (RAYLIB_VERSION_MAJOR == 5 && RAYLIB_VERSION_MINOR >= 5))
#define RR_LINES(r, rd, sg, c) DrawRectangleRoundedLines(r, rd, sg, c)
#else
#define RR_LINES(r, rd, sg, c) DrawRectangleRoundedLines(r, rd, sg, 2.0f, c)
#endif

