static Texture2D texTable, texGun, texShellRed, texShellGold;
static Sound sClick, sCock, sBang;

// ---------------- Random core (same logic as the C core of the web version) ----------------
static uint32_t rngState = 2463534242u;
static uint32_t NextU32(void) { rngState ^= rngState << 13; rngState ^= rngState >> 17; rngState ^= rngState << 5; return rngState; }
static void RR_Seed(uint32_t s) { rngState = s ? s : 2463534242u; for (int i = 0; i < 8; i++) NextU32(); }
static double RR_Rand01(void) { return NextU32() / 4294967296.0; }
static int RR_Pick(int n) {
    if (n <= 1) return 0;
    uint32_t limit = UINT32_MAX - (UINT32_MAX % (uint32_t)n), r;
    do { r = NextU32(); } while (r >= limit);
    return (int)(r % (uint32_t)n);
}
static double RR_SlotAngle(int n, int i) { return -TAU / 4.0 + i * (TAU / n); }
static double RR_Target(double cur, int n, int win, int turns, double jit) {
    double aim = RR_SlotAngle(n, win) + jit * (TAU / n);
    double d = fmod(aim - cur, TAU);
    if (d < 0) d += TAU;
    return cur + d + turns * TAU;
}
static double RR_Ease(double t) { if (t <= 0) return 0; if (t >= 1) return 1; double u = 1.0 - t; return 1.0 - u*u*u*u*u; }

// ---------------- Tiny baseline-JPEG decoder ----------------
// Many raylib builds are compiled WITHOUT JPG support (it is off by default), which makes
// LoadImageFromMemory(".jpg") fail. The background is a JPEG (small file), so we decode it here.
// BEGIN JPEG
typedef struct { const unsigned char* d; int n, p; unsigned int buf; int cnt; } JStream;
typedef struct { unsigned char bits[17]; unsigned char val[256]; } JHuff;
static const unsigned char J_ZZ[64] = {
     0, 1, 8,16, 9, 2, 3,10,17,24,32,25,18,11, 4, 5,12,19,26,33,40,48,41,34,27,20,13, 6, 7,14,21,28,
    35,42,49,56,57,50,43,36,29,22,15,23,30,37,44,51,58,59,52,45,38,31,39,46,53,60,61,54,47,55,62,63 };

static int J_Bit(JStream* s) {
    if (s->cnt == 0) {
        int b = (s->p < s->n) ? s->d[s->p++] : 0;
        if (b == 0xFF) {
            int b2 = (s->p < s->n) ? s->d[s->p] : 0;
            if (b2 == 0) s->p++;            // stuffed 0xFF00 -> 0xFF
            else { s->p--; b = 0; }         // real marker: feed zeros, stay on it
        }
        s->buf = (unsigned int)b; s->cnt = 8;
    }
    s->cnt--;
    return (int)((s->buf >> s->cnt) & 1u);
}
static int J_Recv(JStream* s, int n) { int v = 0; while (n-- > 0) v = (v << 1) | J_Bit(s); return v; }
static int J_Extend(int v, int n) { return (n > 0 && v < (1 << (n - 1))) ? v - (1 << n) + 1 : v; }
static int J_Huff(JStream* s, const JHuff* h) {
    int code = 0, first = 0, index = 0;
    for (int len = 1; len <= 16; len++) {
        code |= J_Bit(s);
        int count = h->bits[len];
        if (code - count < first) return h->val[(index + (code - first)) & 255];
        index += count; first += count; first <<= 1; code <<= 1;
    }
    return 0;
}

// Returns a malloc'd RGB (3 bytes/pixel) buffer, or NULL if the file is not a baseline JPEG.
static unsigned char* RR_DecodeJPEG(const unsigned char* d, int n, int* outW, int* outH) {
    int p = 2, W = 0, H = 0, nc = 0, ri = 0, ok = 0;
    int qt[4][64]; memset(qt, 0, sizeof qt);
    JHuff hdc[4], hac[4]; memset(hdc, 0, sizeof hdc); memset(hac, 0, sizeof hac);
    int cid[4] = { 0 }, ch[4] = { 0 }, cv[4] = { 0 }, cq[4] = { 0 }, cdc[4] = { 0 }, cac[4] = { 0 };
    if (n < 4 || d[0] != 0xFF || d[1] != 0xD8) return NULL;
    while (p + 4 <= n) {
        if (d[p] != 0xFF) { p++; continue; }
        int m = d[p + 1], len = (d[p + 2] << 8) | d[p + 3];
        if (m == 0xFF) { p++; continue; }
        const unsigned char* s = d + p + 4; int sl = len - 2;
        if (m == 0xDB) {
            int i = 0;
            while (i < sl) {
                int pq = s[i] >> 4, tq = s[i] & 3; i++;
                for (int k = 0; k < 64; k++) { qt[tq][k] = pq ? ((s[i] << 8) | s[i + 1]) : s[i]; i += pq ? 2 : 1; }
            }
        } else if (m == 0xC0 || m == 0xC1) {
            H = (s[1] << 8) | s[2]; W = (s[3] << 8) | s[4]; nc = s[5];
            if (s[0] != 8 || nc < 1 || nc > 3 || W <= 0 || H <= 0) return NULL;
            for (int i = 0; i < nc; i++) { cid[i] = s[6 + i * 3]; ch[i] = s[7 + i * 3] >> 4; cv[i] = s[7 + i * 3] & 15; cq[i] = s[8 + i * 3] & 3; }
            ok = 1;
        } else if (m == 0xC2 || m == 0xC3 || (m >= 0xC5 && m <= 0xCF && m != 0xC8 && m != 0xCC)) {
            return NULL;                      // progressive / lossless / arithmetic: not supported
        } else if (m == 0xC4) {
            int i = 0;
            while (i < sl) {
                int tc = s[i] >> 4, th = s[i] & 3; i++;
                JHuff* h = tc ? &hac[th] : &hdc[th]; int tot = 0;
                for (int k = 1; k <= 16; k++) { h->bits[k] = s[i++]; tot += h->bits[k]; }
                for (int k = 0; k < tot && k < 256; k++) h->val[k] = s[i++];
            }
        } else if (m == 0xDD) {
            ri = (s[0] << 8) | s[1];
        } else if (m == 0xDA) {
            if (!ok) return NULL;
            int ns = s[0];
            if (ns != nc) return NULL;
            for (int i = 0; i < ns; i++) for (int c = 0; c < nc; c++) if (cid[c] == s[1 + i * 2]) { cdc[c] = s[2 + i * 2] >> 4; cac[c] = s[2 + i * 2] & 3; }
            p += 2 + len; break;
        }
        p += 2 + len;
    }
    if (!ok) return NULL;

    int hmax = 1, vmax = 1;
    for (int c = 0; c < nc; c++) { if (ch[c] > hmax) hmax = ch[c]; if (cv[c] > vmax) vmax = cv[c]; if (!ch[c] || !cv[c]) return NULL; }
    int mcux = (W + 8 * hmax - 1) / (8 * hmax), mcuy = (H + 8 * vmax - 1) / (8 * vmax);
    unsigned char* plane[3] = { 0 }; int pw[3], ph[3];
    for (int c = 0; c < nc; c++) {
        pw[c] = mcux * ch[c] * 8; ph[c] = mcuy * cv[c] * 8;
        plane[c] = (unsigned char*)MemAlloc((unsigned int)(pw[c] * ph[c]));
        if (!plane[c]) { for (int k = 0; k < c; k++) MemFree(plane[k]); return NULL; }
    }
    float cs[8][8];   // cs[x][u] = C(u)/2 * cos((2x+1)u*pi/16)
    for (int x = 0; x < 8; x++) for (int u = 0; u < 8; u++) cs[x][u] = (u ? 1.0f : 0.70710678f) * 0.5f * cosf((2 * x + 1) * u * 3.14159265f / 16.0f);

    JStream st = { d, n, p, 0, 0 };
    int pred[3] = { 0, 0, 0 }, mcuCount = 0;
    for (int my = 0; my < mcuy; my++) for (int mx = 0; mx < mcux; mx++) {
        if (ri && mcuCount > 0 && mcuCount % ri == 0) {   // restart marker: realign and reset DC prediction
            st.cnt = 0;
            while (st.p + 1 < st.n && !(st.d[st.p] == 0xFF && st.d[st.p + 1] >= 0xD0 && st.d[st.p + 1] <= 0xD7)) st.p++;
            st.p += 2; pred[0] = pred[1] = pred[2] = 0;
        }
        mcuCount++;
        for (int c = 0; c < nc; c++) for (int by = 0; by < cv[c]; by++) for (int bx = 0; bx < ch[c]; bx++) {
            int F[64]; memset(F, 0, sizeof F);
            int t = J_Huff(&st, &hdc[cdc[c]]);
            pred[c] += t ? J_Extend(J_Recv(&st, t), t) : 0;
            F[0] = pred[c] * qt[cq[c]][0];
            for (int k = 1; k < 64;) {
                int rs = J_Huff(&st, &hac[cac[c]]), r = rs >> 4, sz = rs & 15;
                if (sz == 0) { if (r == 15) { k += 16; continue; } break; }
                k += r; if (k > 63) break;
                F[J_ZZ[k]] = J_Extend(J_Recv(&st, sz), sz) * qt[cq[c]][k];
                k++;
            }
            float tmp[64];
            for (int v = 0; v < 8; v++) for (int x = 0; x < 8; x++) {
                float a = 0; for (int u = 0; u < 8; u++) a += cs[x][u] * (float)F[v * 8 + u];
                tmp[v * 8 + x] = a;
            }
            int ox = (mx * ch[c] + bx) * 8, oy = (my * cv[c] + by) * 8;
            for (int y = 0; y < 8; y++) for (int x = 0; x < 8; x++) {
                float a = 128.0f; for (int v = 0; v < 8; v++) a += cs[y][v] * tmp[v * 8 + x];
                int iv = (int)floorf(a + 0.5f); if (iv < 0) iv = 0; if (iv > 255) iv = 255;
                plane[c][(oy + y) * pw[c] + ox + x] = (unsigned char)iv;
            }
        }
    }
    unsigned char* rgb = (unsigned char*)MemAlloc((unsigned int)(W * H * 3));
    if (rgb) for (int y = 0; y < H; y++) for (int x = 0; x < W; x++) {
        int v[3];
        for (int c = 0; c < nc; c++) v[c] = plane[c][(y * cv[c] / vmax) * pw[c] + (x * ch[c] / hmax)];
        float R, G, B;
        if (nc == 1) { R = G = B = (float)v[0]; }
        else {
            float Y = (float)v[0], Cb = (float)v[1] - 128.0f, Cr = (float)v[2] - 128.0f;
            R = Y + 1.402f * Cr; G = Y - 0.344136f * Cb - 0.714136f * Cr; B = Y + 1.772f * Cb;
        }
        unsigned char* o = rgb + (y * W + x) * 3;
        o[0] = (unsigned char)(R < 0 ? 0 : R > 255 ? 255 : (int)(R + 0.5f));
        o[1] = (unsigned char)(G < 0 ? 0 : G > 255 ? 255 : (int)(G + 0.5f));
        o[2] = (unsigned char)(B < 0 ? 0 : B > 255 ? 255 : (int)(B + 0.5f));
    }
    for (int c = 0; c < nc; c++) MemFree(plane[c]);
    if (rgb) { *outW = W; *outH = H; }
    return rgb;
}
// END JPEG

// ---------------- Assets ----------------
static unsigned char* LoadBase64(const char* b64, int* len) { return DecodeDataBase64((unsigned char*)b64, len); }

static Texture2D LoadAsset(const char* file, const char* ext, const char* b64) {
    Texture2D t = { 0 };
    if (b64) {   // images stored inside this file as base64
        int len = 0;
        unsigned char* raw = LoadBase64(b64, &len);
        if (raw) {
            Image im = { 0 };
            if (strcmp(ext, ".jpg") == 0) {   // built-in decoder first: works even if raylib has no JPG support
                int w = 0, h = 0;
                unsigned char* px = RR_DecodeJPEG(raw, len, &w, &h);
                if (px) { im.data = px; im.width = w; im.height = h; im.mipmaps = 1; im.format = PIXELFORMAT_UNCOMPRESSED_R8G8B8; }
            }
            if (!im.data) im = LoadImageFromMemory(ext, raw, len);
            if (im.data) { t = LoadTextureFromImage(im); UnloadImage(im); }
            MemFree(raw);
        }
    }
    if (t.id == 0) t = LoadTexture(file);   // optional assets/ folder; a missing file just gives id 0
    if (t.id != 0) SetTextureFilter(t, TEXTURE_FILTER_BILINEAR);
    return t;
}

// ---------------- Fonts (DejaVu Sans, embedded; Latin + Cyrillic) ----------------
static const int FONT_SIZES[3] = { 20, 36, 64 };   // each font is built at 3 sizes so text stays sharp
static Font fontReg[3], fontBold[3];
static bool fontOK = false;
static float gTextScale = 1.0f;                    // extra zoom (camera) applied to text being drawn

static void LoadFonts(void) {
    int cps[256], n = 0;
    for (int c = 32; c <= 126; c++) cps[n++] = c;
    cps[n++] = 0x401; for (int c = 0x410; c <= 0x44F; c++) cps[n++] = c; cps[n++] = 0x451;
    cps[n++] = 0xD7; cps[n++] = 0x2026; cps[n++] = 0x2013; cps[n++] = 0x2014;
    const char* src[2] = { B64_FONT_REG, B64_FONT_BOLD };
    Font* dst[2] = { fontReg, fontBold };
    fontOK = true;
    for (int f = 0; f < 2; f++) {
        int len = 0;
        unsigned char* raw = LoadBase64(src[f], &len);
        if (!raw) { fontOK = false; continue; }
        for (int i = 0; i < 3; i++) {
            dst[f][i] = LoadFontFromMemory(".ttf", raw, len, FONT_SIZES[i], cps, n);
            if (dst[f][i].texture.id) SetTextureFilter(dst[f][i].texture, TEXTURE_FILTER_BILINEAR);
        }
        MemFree(raw);
    }
}
static void UnloadFonts(void) {
    if (!fontOK) return;
    for (int i = 0; i < 3; i++) { UnloadFont(fontReg[i]); UnloadFont(fontBold[i]); }
}
static Font PickFont(bool bold, float size) {
    Font* set = bold ? fontBold : fontReg;
    float want = size * gTextScale;
    for (int i = 0; i < 2; i++) if (want <= FONT_SIZES[i] * 1.05f) return set[i];
    return set[2];
}
static void Txt(const char* t, float x, float y, float size, Color c, bool bold) {
    if (!fontOK) { DrawText(t, (int)x, (int)y, (int)size, c); return; }
    DrawTextEx(PickFont(bold, size), t, (Vector2){ x, y }, size, 0.0f, c);
}
static float TxtW(const char* t, float size, bool bold) {
    if (!fontOK) return (float)MeasureText(t, (int)size);
    return MeasureTextEx(PickFont(bold, size), t, size, 0.0f).x;
}
static void TxtC(const char* t, float cx, float y, float size, Color c, bool bold) { Txt(t, cx - TxtW(t, size, bold) / 2.0f, y, size, c, bold); }

static float Noise(void) { return (float)GetRandomValue(-10000, 10000) / 10000.0f; }

static Sound MakeSound(int kind) {   // 0 click, 1 cock (two clicks), 2 bang
    const int sr = 44100;
    float dur = (kind == 0) ? 0.05f : (kind == 1) ? 0.16f : 1.3f;
    int n = (int)(sr * dur);
    short* d = (short*)MemAlloc(n * sizeof(short));
    float lp = 0.0f, phase = 0.0f;
    for (int i = 0; i < n; i++) {
        float t = (float)i / sr, v = 0.0f;
        if (kind == 0) {
            v = Noise() * sinf(6.2831853f * 1800.0f * t) * expf(-t * 110.0f) * 0.8f;
        } else if (kind == 1) {
            float t2 = t - 0.09f;
            v = Noise() * sinf(6.2831853f * 1000.0f * t) * expf(-t * 90.0f);
            if (t2 > 0) v += Noise() * sinf(6.2831853f * 1400.0f * t2) * expf(-t2 * 90.0f);
            v *= 0.8f;
        } else {
            float cutoff = 0.05f + 0.75f * expf(-t * 7.0f);       // noise gets darker as it fades
            lp += cutoff * (Noise() - lp);
            float f = 35.0f + 95.0f * expf(-t * 12.0f);
            phase += 6.2831853f * f / sr;
            v = lp * expf(-t * 4.5f) * 1.6f + sinf(phase) * expf(-t * 8.0f) * 0.9f;
        }
        if (v > 1.0f) v = 1.0f;
        if (v < -1.0f) v = -1.0f;
        d[i] = (short)(v * 30000.0f);
    }
    Wave w = { 0 };
    w.frameCount = (unsigned int)n; w.sampleRate = sr; w.sampleSize = 16; w.channels = 1; w.data = d;
    Sound s = LoadSoundFromWave(w);
    UnloadWave(w);
    return s;
}

static void Play(Sound s, float pitch) {
    if (!soundOn || !IsAudioDeviceReady()) return;
    SetSoundPitch(s, pitch);
    PlaySound(s);
}

// ---------------- Helpers ----------------
static bool Button(Rectangle r, const char* label, float size, Color accent, bool active, bool enabled) {
    Vector2 m = GetMousePosition();
    bool hover = enabled && CheckCollisionPointRec(m, r);
    DrawRectangleRounded(r, 0.25f, 6, active ? COLOR_CARD_ACTIVE : (hover ? COLOR_CARD_HOVER : COLOR_CARD));
    RR_LINES(r, 0.25f, 6, (active || hover) ? accent : COLOR_LINE);
    Txt(label, r.x + (r.width - TxtW(label, size, true)) / 2.0f, r.y + (r.height - size) / 2.0f - 1.0f, size,
        !enabled ? COLOR_DIM : (active ? accent : COLOR_INK), true);
    return hover && IsMouseButtonPressed(MOUSE_BUTTON_LEFT);
}

static bool AllowedCp(int c) { return (c >= 32 && c <= 126) || c == 0x401 || c == 0x451 || (c >= 0x410 && c <= 0x44F); }
static int Utf8Chars(const char* s) { int n = 0; for (; *s; s++) if (((unsigned char)*s & 0xC0) != 0x80) n++; return n; }
static int CmpNames(const void* a, const void* b) {
    const unsigned char *x = (const unsigned char*)a, *y = (const unsigned char*)b;
    while (*x && *y) { int cx = tolower(*x), cy = tolower(*y); if (cx != cy) return cx - cy; x++; y++; }
    return (int)*x - (int)*y;
}

static void ClearResult(void) { winner = -1; removePending = false; popupOpen = false; if (state == STATE_RESULT) state = STATE_READY; }
static void ResetNames(void) {
    const char* d[] = { "Alexei", "Dmitri", "Natasha", "Ivan", "Sasha", "Olga" };
    nameCount = 6;
    for (int i = 0; i < 6; i++) snprintf(names[i], sizeof names[i], "%s", d[i]);
    ClearResult(); listScroll = 0.0f;
}
static void AddName(void) {
    if (inputLen == 0 || nameCount >= MAX_NAMES) return;
    snprintf(names[nameCount++], sizeof names[0], "%s", inputBuf);
    inputLen = 0; inputBuf[0] = '\0';
    ClearResult(); scrollToEnd = true;
}
static void RemoveName(int idx) {
    for (int i = idx; i < nameCount - 1; i++) memcpy(names[i], names[i + 1], sizeof names[0]);
    if (nameCount > 0) nameCount--;
}
static void ShuffleNames(void) {
    for (int i = nameCount - 1; i > 0; i--) {
        int j = RR_Pick(i + 1);
        char tmp[NAME_LEN]; memcpy(tmp, names[i], sizeof tmp); memcpy(names[i], names[j], sizeof tmp); memcpy(names[j], tmp, sizeof tmp);
    }
    ClearResult();
}
// Closes the winner popup; if "remove" is pending the chosen name is taken off the list now.
static void ClosePopup(void) {
    popupOpen = false;
    if (removePending && winner >= 0) { RemoveName(winner); winner = -1; state = STATE_READY; }
    removePending = false;
}
static void StartSpin(void) {
    if (state == STATE_SPINNING) return;
    ClosePopup();
    if (nameCount < 2) return;
    winner = RR_Pick(nameCount);
    spinFrom = angle;
    spinTo = RR_Target(spinFrom, nameCount, winner, 5 + RR_Pick(3), (RR_Rand01() - 0.5) * 0.6);
    spinStart = GetTime(); lastTick = 0;
    lastSlot = (int)floor((spinFrom + TAU / 4) / (TAU / nameCount) + 0.5);
    state = STATE_SPINNING; removePending = false;
    Play(sCock, 1.0f);
}

// Typing into the "add a name" box (UTF-8, Latin + Cyrillic)
static void UpdateTextInput(void) {
    int key = GetCharPressed();
    while (key > 0) {
        if (inputFocus && AllowedCp(key) && Utf8Chars(inputBuf) < MAX_CHARS) {
            int sz = 0; const char* u = CodepointToUTF8(key, &sz);
            if (sz > 0 && inputLen + sz < NAME_LEN) { memcpy(inputBuf + inputLen, u, (size_t)sz); inputLen += sz; inputBuf[inputLen] = '\0'; }
        }
        key = GetCharPressed();   // when the box is not focused the characters are simply discarded
    }
    if (!inputFocus) return;
    static float bsHold = 0.0f;   // hold backspace to keep deleting
    bool del = false;
    if (IsKeyPressed(KEY_BACKSPACE)) { del = true; bsHold = 0.0f; }
    else if (IsKeyDown(KEY_BACKSPACE)) {
        float before = bsHold; bsHold += GetFrameTime();
        if (bsHold > 0.4f && (int)((bsHold - 0.4f) / 0.05f) != (int)((before - 0.4f) / 0.05f)) del = true;
    }
    if (del && inputLen > 0) {
        while (inputLen > 0 && ((unsigned char)inputBuf[inputLen - 1] & 0xC0) == 0x80) inputLen--;
        if (inputLen > 0) inputLen--;
        inputBuf[inputLen] = '\0';
    }
    if (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_KP_ENTER)) AddName();
}

// ---------------- Drawing: table scene ----------------
static void DrawBackground(Rectangle area, Vector2 center, float bs, float u, Vector2 shake) {
    if (texTable.id) {   // the picture is scaled to COVER the whole play area (no empty borders)
        Rectangle dst = { center.x + shake.x - CX * bs, center.y + shake.y - CY * bs, DESIGN_W * bs, DESIGN_H * bs };
        DrawTexturePro(texTable, (Rectangle){ 0, 0, (float)texTable.width, (float)texTable.height }, dst, (Vector2){ 0, 0 }, 0, WHITE);
    } else {
        DrawRectangleRec(area, (Color){ 22, 18, 16, 255 });
        DrawCircle((int)center.x, (int)center.y, 345 * u, (Color){ 96, 62, 40, 255 });
        DrawRectangleRounded((Rectangle){ center.x - 130 * u, center.y - 95 * u, 260 * u, 190 * u }, 0.05f, 6, (Color){ 40, 44, 41, 255 });
    }
}

static void DrawShells(void) {
    if (texShellGold.id) DrawTexturePro(texShellGold, (Rectangle){ 0, 0, (float)texShellGold.width, (float)texShellGold.height }, (Rectangle){ 190, 455, 44, 40 }, (Vector2){ 0, 0 }, 0, WHITE);
    if (texShellRed.id) DrawTexturePro(texShellRed, (Rectangle){ 0, 0, (float)texShellRed.width, (float)texShellRed.height }, (Rectangle){ 240, 470, 52, 40 }, (Vector2){ 0, 0 }, 0, WHITE);
}

static void DrawNameTags(void) {
    float fs = nameCount <= 8 ? 26.0f : (nameCount <= 12 ? 22.0f : 18.0f);
    for (int i = 0; i < nameCount; i++) {
        double a = RR_SlotAngle(nameCount, i);
        float x = CX + (float)cos(a) * TAG_R * 1.12f, y = CY + (float)sin(a) * TAG_R * 0.86f;
        float tw = TxtW(names[i], fs, true), w = tw + 28, h = fs + 16;
        Rectangle r = { x - w / 2, y - h / 2, w, h };
        bool win = (i == winner && (state == STATE_RESULT));
        if (win) DrawRectangleRounded((Rectangle){ r.x - 8, r.y - 8, r.width + 16, r.height + 16 }, 0.3f, 6, Fade(COLOR_BLOOD_HI, 0.30f));
        DrawRectangleRounded(r, 0.2f, 6, win ? (Color){ 110, 23, 18, 255 } : (Color){ 20, 18, 16, 230 });
        RR_LINES(r, 0.2f, 6, win ? COLOR_BLOOD_HI : COLOR_LINE);
        Txt(names[i], x - tw / 2.0f, y - fs / 2.0f - 1.0f, fs, win ? (Color){ 255, 241, 214, 255 } : COLOR_INK, true);
    }
}

static void DrawGun(double now) {
    if (!texGun.id) {   // no image: build the shotgun from rectangles
        float ca = (float)cos(angle), sa = (float)sin(angle), deg = (float)(angle * 180.0 / 3.14159265358979);
        float parts[][4] = { { -215, -17, 150, 36 }, { -75, -10, 55, 22 }, { -40, -15, 70, 28 }, { -10, -14, 225, 13 }, { -10, 1, 225, 13 } };
        Color cols[] = { (Color){ 110, 66, 38, 255 }, (Color){ 90, 54, 32, 255 }, (Color){ 120, 110, 95, 255 }, (Color){ 58, 60, 64, 255 }, (Color){ 48, 50, 54, 255 } };
        for (int i = 0; i < 5; i++) {
            Vector2 o = { CX + ca * parts[i][0] - sa * parts[i][1], CY + sa * parts[i][0] + ca * parts[i][1] };
            DrawRectanglePro((Rectangle){ o.x, o.y, parts[i][2], parts[i][3] }, (Vector2){ 0, 0 }, deg, cols[i]);
        }
        return;
    }
    float gh = GUN_W * texGun.height / texGun.width, db = (float)(now - bangTime);
    float kick = (db >= 0 && db < 0.5f) ? -16.0f * expf(-db / 0.11f) : 0.0f;
    float deg = (float)(angle * 180.0 / 3.14159265358979);
    Rectangle src = { 0, 0, (float)texGun.width, (float)texGun.height };
    Vector2 org = { GUN_W / 2, gh / 2 };
    float px = CX + (float)cos(angle) * kick, py = CY + (float)sin(angle) * kick;
    DrawTexturePro(texGun, src, (Rectangle){ px + 6, py + 10, GUN_W, gh }, org, deg, (Color){ 0, 0, 0, 110 });
    DrawTexturePro(texGun, src, (Rectangle){ px, py, GUN_W, gh }, org, deg, WHITE);
    if (db >= 0 && db < 0.16f) {   // muzzle flash
        float k = 1.0f - db / 0.16f, mx = px + (float)cos(angle) * (GUN_W / 2 + 8), my = py + (float)sin(angle) * (GUN_W / 2 + 8);
        DrawCircle((int)mx, (int)my, 70 * k, (Color){ 255, 80, 0, (unsigned char)(70 * k) });
        DrawCircle((int)mx, (int)my, 45 * k, (Color){ 255, 170, 50, (unsigned char)(160 * k) });
        DrawCircle((int)mx, (int)my, 22 * k, (Color){ 255, 248, 210, (unsigned char)(240 * k) });
    }
}

// ---------------- Drawing: side panel (like wheelofnames.com) ----------------
static bool FireButton(Rectangle r) {
    bool canFire = nameCount - (removePending ? 1 : 0) >= 2 && state != STATE_SPINNING;
    const char* label = state == STATE_SPINNING ? "SPINNING..." : (nameCount < 2 ? "ADD 2+ NAMES" : "PULL THE TRIGGER  [SPACE]");
    return Button(r, label, 18, COLOR_BLOOD_HI, canFire, canFire) && canFire;
}

static void DrawPanel(int sw, int sh, float pw) {
    float px = sw - pw, m = 18, iw = pw - 2 * m, tabH = 48, hideW = 46;
    bool idle = state != STATE_SPINNING;
    Vector2 mouse = GetMousePosition();
    DrawRectangle((int)px, 0, (int)pw, sh, COLOR_PANEL);
    DrawLineEx((Vector2){ px, 0 }, (Vector2){ px, (float)sh }, 2.0f, COLOR_LINE);

    // tabs + hide button
    const char* tabNames[2] = { "ENTRIES", "OPTIONS" };
    float tw = (pw - hideW) / 2;
    for (int i = 0; i < 2; i++) {
        Rectangle t = { px + i * tw, 0, tw, tabH };
        bool hov = CheckCollisionPointRec(mouse, t), act = (panelTab == i);
        DrawRectangleRec(t, act ? COLOR_PANEL : (hov ? COLOR_CARD_HOVER : COLOR_FIELD));
        if (act) DrawRectangle((int)t.x, (int)tabH - 3, (int)t.width, 3, COLOR_BRASS);
        TxtC(tabNames[i], t.x + t.width / 2, 15, 16, act ? COLOR_BRASS : COLOR_DIM, true);
        if (hov && IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) { panelTab = i; inputFocus = false; }
    }
    Rectangle hb = { (float)sw - hideW, 0, hideW, tabH };
    bool hhov = CheckCollisionPointRec(mouse, hb);
    DrawRectangleRec(hb, hhov ? COLOR_CARD_HOVER : COLOR_FIELD);
    TxtC(">>", hb.x + hideW / 2, 14, 18, hhov ? COLOR_BRASS : COLOR_DIM, true);
    if (hhov && IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) { panelOpen = false; inputFocus = false; }
    DrawLineEx((Vector2){ px, tabH }, (Vector2){ (float)sw, tabH }, 1.5f, COLOR_LINE);

    Rectangle fire = { px + m, (float)sh - 20 - 58, iw, 58 };
    float y = tabH + 16;

    if (panelTab == 0) {
        Txt(TextFormat("ENTRIES  %d / %d", nameCount, MAX_NAMES), px + m, y, 15, COLOR_DIM, true);
        y += 26;
        const char* acts[4] = { "Shuffle", "Sort", "Reset", "Clear" };
        float bw = (iw - 3 * 8) / 4;
        for (int i = 0; i < 4; i++) {
            if (Button((Rectangle){ px + m + i * (bw + 8), y, bw, 34 }, acts[i], 14, COLOR_BRASS, false, idle)) {
                if (i == 0) ShuffleNames();
                else if (i == 1) { qsort(names, (size_t)nameCount, sizeof names[0], CmpNames); ClearResult(); }
                else if (i == 2) ResetNames();
                else { nameCount = 0; ClearResult(); listScroll = 0.0f; }
            }
        }
        y += 34 + 12;
        Rectangle field = { px + m, fire.y - 14 - 46, iw - 92, 46 };
        Rectangle addBtn = { field.x + field.width + 8, field.y, 84, 46 };
        Rectangle listR = { px + m, y, iw, field.y - 12 - y };

        // list of entries (scrollable)
        const float pitch = 40.0f, rowH = 36.0f;
        float content = nameCount * pitch, maxScroll = fmaxf(0.0f, content - listR.height);
        bool inList = CheckCollisionPointRec(mouse, listR);
        if (inList) listScroll -= GetMouseWheelMove() * pitch;
        if (scrollToEnd) { listScroll = maxScroll; scrollToEnd = false; }
        if (listScroll < 0) listScroll = 0;
        if (listScroll > maxScroll) listScroll = maxScroll;
        DrawRectangleRounded(listR, 0.03f, 6, COLOR_FIELD);
        BeginScissorMode((int)listR.x, (int)listR.y, (int)listR.width, (int)listR.height);
        int rem = -1;
        float rw = listR.width - (maxScroll > 0 ? 10 : 0);
        if (nameCount == 0) TxtC("Add some names below", listR.x + listR.width / 2, listR.y + 20, 17, COLOR_DIM, false);
        for (int i = 0; i < nameCount; i++) {
            Rectangle row = { listR.x + 2, listR.y + 2 + i * pitch - listScroll, rw - 4, rowH };
            if (row.y + row.height < listR.y || row.y > listR.y + listR.height) continue;
            bool win = (i == winner && state == STATE_RESULT);
            DrawRectangleRounded(row, 0.2f, 6, win ? (Color){ 110, 23, 18, 255 } : COLOR_CARD);
            Txt(TextFormat("%d", i + 1), row.x + 12, row.y + 9, 16, win ? COLOR_INK : COLOR_DIM, false);
            Txt(names[i], row.x + 44, row.y + 8, 19, COLOR_INK, false);
            if (Button((Rectangle){ row.x + row.width - 34, row.y + 5, 26, 26 }, "x", 16, COLOR_BLOOD_HI, false, idle && inList)) rem = i;
        }
        EndScissorMode();
        if (maxScroll > 0) {
            float bh = fmaxf(30.0f, listR.height * listR.height / content);
            float by = listR.y + (listR.height - bh) * (listScroll / maxScroll);
            DrawRectangleRounded((Rectangle){ listR.x + listR.width - 8, by, 5, bh }, 1.0f, 4, COLOR_LINE);
        }
        if (rem >= 0) { RemoveName(rem); ClearResult(); }

        // add-a-name box
        if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) inputFocus = CheckCollisionPointRec(mouse, field);
        DrawRectangleRounded(field, 0.2f, 6, COLOR_FIELD);
        RR_LINES(field, 0.2f, 6, inputFocus ? COLOR_BRASS : COLOR_LINE);
        BeginScissorMode((int)field.x + 4, (int)field.y, (int)field.width - 8, (int)field.height);
        float ty = field.y + (field.height - 20) / 2 - 1;
        if (inputLen == 0) Txt("Type a name...", field.x + 14, ty, 20, COLOR_DIM, false);
        else {
            float w = TxtW(inputBuf, 20, false), maxw = field.width - 30, tx = field.x + 14 - (w > maxw ? w - maxw : 0);
            Txt(inputBuf, tx, ty, 20, COLOR_INK, false);
            if (inputFocus && ((int)(GetTime() * 2)) % 2 == 0) DrawRectangle((int)(tx + w + 2), (int)field.y + 11, 2, (int)field.height - 22, COLOR_BRASS);
        }
        if (inputLen == 0 && inputFocus && ((int)(GetTime() * 2)) % 2 == 0) DrawRectangle((int)field.x + 12, (int)field.y + 11, 2, (int)field.height - 22, COLOR_BRASS);
        EndScissorMode();
        if (Button(addBtn, "Add", 17, COLOR_BRASS, false, inputLen > 0 && nameCount < MAX_NAMES && idle)) { AddName(); inputFocus = true; }
    } else {
        Txt("OPTIONS", px + m, y, 15, COLOR_DIM, true); y += 28;
        if (Button((Rectangle){ px + m, y, iw, 44 }, soundOn ? "Sound: ON" : "Sound: OFF", 17, COLOR_BRASS, soundOn, true)) soundOn = !soundOn;
        y += 54;
        if (Button((Rectangle){ px + m, y, iw, 44 }, removeAfter ? "Remove winner after spin: ON" : "Remove winner after spin: OFF", 16, COLOR_BLOOD_HI, removeAfter, true)) removeAfter = !removeAfter;
        y += 62;
        Txt("SPIN TIME", px + m, y, 15, COLOR_DIM, true); y += 26;
        const float secs[4] = { 3.0f, 6.0f, 9.0f, 15.0f };
        float bw = (iw - 3 * 8) / 4;
        for (int i = 0; i < 4; i++)
            if (Button((Rectangle){ px + m + i * (bw + 8), y, bw, 40 }, TextFormat("%ds", (int)secs[i]), 16, COLOR_BRASS, spinSeconds == secs[i], idle)) spinSeconds = secs[i];
        y += 62;
        if (Button((Rectangle){ px + m, y, iw, 44 }, "Fullscreen  [F]", 16, COLOR_BRASS, IsWindowFullscreen(), true)) ToggleFullscreen();
        y += 54;
        if (Button((Rectangle){ px + m, y, iw, 44 }, "Hide this panel  [H]", 16, COLOR_BRASS, false, true)) panelOpen = false;
        y += 62;
        Txt("Keys:  SPACE / ENTER = fire,  S = options,", px + m, y, 14, COLOR_DIM, false);
        Txt("R = reset names,  F = fullscreen,  H = hide panel", px + m, y + 20, 14, COLOR_DIM, false);
    }
    if (FireButton(fire)) StartSpin();
}

// ---------------- Drawing: "who was selected" popup ----------------
static void DrawWinnerPopup(Rectangle area, Vector2 center, double now) {
    if (!popupOpen || winner < 0 || now < popupStart) return;
    float t = (float)fmin(1.0, (now - popupStart) / 0.25), e = 1.0f - (1.0f - t) * (1.0f - t);   // slide/fade in
    DrawRectangleRec(area, Fade((Color){ 6, 5, 4, 255 }, 0.62f * e));
    float w = fminf(480.0f, area.width - 40), h = 270.0f;
    Rectangle card = { center.x - w / 2, center.y - h / 2 + (1.0f - e) * 40.0f, w, h };
    DrawRectangleRounded((Rectangle){ card.x - 10, card.y - 10, card.width + 20, card.height + 20 }, 0.08f, 8, Fade(COLOR_BLOOD_HI, 0.25f * e));
    DrawRectangleRounded(card, 0.06f, 8, COLOR_PANEL);
    RR_LINES(card, 0.06f, 8, COLOR_BLOOD_HI);
    TxtC("IN THE SIGHTS", center.x, card.y + 24, 16, COLOR_BRASS, true);
    float fs = 56;
    while (fs > 22 && TxtW(names[winner], fs, true) > card.width - 48) fs -= 2;
    TxtC(names[winner], center.x, card.y + 62 + (56 - fs) / 2, fs, COLOR_INK, true);
    TxtC("has been chosen", center.x, card.y + 138, 19, COLOR_DIM, false);

    float bw = (card.width - 40 - 2 * 10) / 3, by = card.y + card.height - 72;
    if (Button((Rectangle){ card.x + 20, by, bw, 46 }, "Close", 16, COLOR_BRASS, false, true)) { ClosePopup(); return; }
    if (Button((Rectangle){ card.x + 20 + bw + 10, by, bw, 46 }, "Remove", 16, COLOR_BLOOD_HI, false, true)) { removePending = true; ClosePopup(); return; }
    if (Button((Rectangle){ card.x + 20 + 2 * (bw + 10), by, bw, 46 }, "Spin again", 16, COLOR_BRASS, true, true)) { StartSpin(); return; }
    Vector2 m = GetMousePosition();
    if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT) && CheckCollisionPointRec(m, area) && !CheckCollisionPointRec(m, card)) ClosePopup();   // click outside
}

int main(void) {
    SetConfigFlags(FLAG_MSAA_4X_HINT | FLAG_WINDOW_RESIZABLE);
    InitWindow(1280, 720, "Russian Roulette - Spin Picker");
    SetWindowMinSize(640, 420);
    SetExitKey(KEY_NULL);                       // ESC only un-focuses the text box
    SetTargetFPS(60);
    InitAudioDevice();
    RR_Seed((uint32_t)time(NULL) ^ (uint32_t)(GetTime() * 1e6) ^ 0x9E3779B9u);

    texTable     = LoadAsset("assets/table.png",      ".jpg", B64_TABLE);
    texGun       = LoadAsset("assets/shotgun.png",    ".png", B64_SHOTGUN);
    texShellRed  = LoadAsset("assets/shell_red.png",  ".png", B64_SHELL_RED);
    texShellGold = LoadAsset("assets/shell_gold.png", ".png", B64_SHELL_GOLD);
    LoadFonts();
    sClick = MakeSound(0); sCock = MakeSound(1); sBang = MakeSound(2);
    ResetNames();

    while (!WindowShouldClose()) {
                double now = GetTime();
        int sw = GetScreenWidth(), sh = GetScreenHeight();

        // ---- layout: play area (left) + optional side panel (right) ----
        float pw = panelOpen ? fminf((float)PANEL_W, sw * 0.5f) : 0.0f;
        Rectangle area = { 0, 0, sw - pw, (float)sh };
        Vector2 center = { area.width / 2, area.height / 2 };
        float cover = fmaxf(area.width / DESIGN_W, area.height / DESIGN_H);
        float bs = cover * 1.03f;                                   // background: always covers the whole area
        float u = fminf(fminf(cover, area.height / 500.0f), area.width / 720.0f);   // gun + names: always fully visible
        if (u < 0.3f) u = 0.3f;

        // ---- input ----
        UpdateTextInput();
        if (!inputFocus) {
            if (IsKeyPressed(KEY_H)) panelOpen = !panelOpen;
            if (IsKeyPressed(KEY_S)) { panelOpen = true; panelTab = 1; }
            if (IsKeyPressed(KEY_F)) ToggleFullscreen();
            if (IsKeyPressed(KEY_ESCAPE) && popupOpen) ClosePopup();
            if (state != STATE_SPINNING) {
                if (IsKeyPressed(KEY_R)) ResetNames();
                if (IsKeyPressed(KEY_SPACE) || IsKeyPressed(KEY_ENTER)) StartSpin();
            }
        } else if (IsKeyPressed(KEY_ESCAPE)) inputFocus = false;
        if (!panelOpen) inputFocus = false;

        // ---- update ----
        if (state == STATE_SPINNING) {
            double t = (now - spinStart) / spinSeconds;
            if (t > 1.0) t = 1.0;
            angle = spinFrom + (spinTo - spinFrom) * RR_Ease(t);
            int s = (int)floor((angle + TAU / 4) / (TAU / nameCount) + 0.5);
            if (s != lastSlot && now - lastTick > 0.045) { Play(sClick, 0.9f + (float)t * 0.5f); lastTick = now; }
            lastSlot = s;
            if (t >= 1.0) {
                angle = spinTo; state = STATE_RESULT; bangTime = now;
                removePending = removeAfter; popupOpen = true; popupStart = now + 0.8;   // popup shows after the bang
                Play(sBang, 1.0f);
            }
        }

        // ---- draw ----
        BeginDrawing();
        ClearBackground(COLOR_BG);

        float db = (float)(now - bangTime), shk = (db >= 0 && db < 0.4f) ? (0.4f - db) * 28.0f : 0.0f;
        Vector2 shake = { (float)GetRandomValue(-100, 100) / 100.0f * shk, (float)GetRandomValue(-100, 100) / 100.0f * shk };
        BeginScissorMode(0, 0, (int)area.width, sh);
        DrawBackground(area, center, bs, u, shake);
        Camera2D cam = { 0 };
        cam.offset = (Vector2){ center.x - CX * u + shake.x, center.y - CY * u + shake.y };
        cam.zoom = u;
        BeginMode2D(cam);
        gTextScale = u;
        DrawShells();
        DrawNameTags();
        DrawGun(now);
        gTextScale = 1.0f;
        EndMode2D();
        if (db >= 0 && db < 0.22f) DrawRectangleRec(area, Fade((Color){ 255, 235, 200, 255 }, 0.55f * (1.0f - db / 0.22f)));
        EndScissorMode();

        // result banner
        if (state == STATE_RESULT && winner >= 0 && !(popupOpen && now >= popupStart)) {
            const char* t = TextFormat("IN THE SIGHTS:  %s", names[winner]);
            float fs = 30, w = fminf(TxtW(t, fs, true) + 64, area.width - 24);
            Rectangle b = { center.x - w / 2, 16, w, 58 };
            DrawRectangleRounded(b, 0.3f, 8, (Color){ 20, 18, 16, 235 });
            RR_LINES(b, 0.3f, 8, COLOR_BRASS);
            TxtC(t, center.x, b.y + (b.height - fs) / 2 - 1, fs, COLOR_BRASS, true);
        } else if (state == STATE_SPINNING) {
            TxtC("SPINNING...", center.x, 22, 24, COLOR_INK, true);
        }

        DrawWinnerPopup(area, center, now);

        // side panel, or (when hidden) a small menu button and a fire button
        if (panelOpen) DrawPanel(sw, sh, pw);
        else {
            if (Button((Rectangle){ (float)sw - 122, 14, 108, 40 }, "Menu [H]", 16, COLOR_BRASS, false, true)) panelOpen = true;
            if (FireButton((Rectangle){ center.x - 150, (float)sh - 80, 300, 58 })) StartSpin();
        }
        EndDrawing();
    }

    UnloadSound(sClick); UnloadSound(sCock); UnloadSound(sBang);
    if (texTable.id) UnloadTexture(texTable);
    if (texGun.id) UnloadTexture(texGun);
    if (texShellRed.id) UnloadTexture(texShellRed);
    if (texShellGold.id) UnloadTexture(texShellGold);
    UnloadFonts();
    CloseAudioDevice();
    CloseWindow();
    return 0;
}
